def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release
        if '-' in v:
            version_part, prerelease = v.split('-', 1)
        else:
            version_part = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_ids = prerelease.split('.')
            # Convert to comparable form
            prerelease_tuple = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    prerelease_tuple.append((0, int(identifier)))
                else:
                    prerelease_tuple.append((1, identifier))
            prerelease_tuple = tuple(prerelease_tuple)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(v):
        major, minor, patch, prerelease_tuple = parse_version(v)
        # Version without pre-release sorts after version with pre-release
        # So we use (major, minor, patch, 1 if prerelease is None else 0, prerelease_tuple or ())
        if prerelease_tuple is None:
            return (major, minor, patch, 1)
        else:
            return (major, minor, patch, 0, prerelease_tuple)

    # Use stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

